import { useSyncExternalStore } from "react";
import type { Address, PublicClient } from "viem";
import raw from "@config/sim_addresses.json";
import { normalizeRpcUrl } from "@/chain/rpc";

/**
 * THE RUNTIME SIM OVERLAY (session-81, Option A).
 *
 * The never-deployed layer (WORLD/VITUS/WAR/H2O/GWAT/ENCRYPT) has NO live
 * addresses. Two sources can serve it:
 *
 *  - the harness FIXTURE `config/sim_addresses.json` (GENERATED by set 3;
 *    never hand-edit) — the static fallback the harness/seed path uses;
 *  - the RUNTIME overlay written by the in-frontend bootstrap after a real
 *    fork deploy (localStorage, keyed by the normalized RPC URL; the record
 *    carries the chain id + fork block + deployer). The runtime overlay is
 *    the truth for the user's own fork: addresses are captured from the
 *    actual creation receipts, never assumed to match the fixture.
 *
 * `simAddr` precedence: runtime overlay first, static fixture second.
 * Visibility stays build-gated + LOOPBACK-gated in `chain/simMode.ts`
 * (SIM PREDICATE LAW: a custom real RPC is LIVE, never SIM).
 */

export const SIM_LAYER_NAMES = ["WORLD", "VITUS", "WAR", "H2O", "GWAT", "ENCRYPT"] as const;
export type SimLayerName = (typeof SIM_LAYER_NAMES)[number];

export interface SimLayerConfig {
  $provenance: string;
  pin: number | null;
  deployedBy: string;
  layer: Record<SimLayerName, string>;
  variants: string;
  notes: Record<string, string | null>;
}

export const simLayerConfig = raw as SimLayerConfig;

export interface SimOverlayLayer extends Record<SimLayerName, string> {}

export interface SimOverlayRecord {
  v: 1;
  /** normalized RPC URL this deployment belongs to */
  rpc: string;
  /** the chain id observed at deploy time (369 on a PulseChain fork) */
  chainId: number;
  /** the impersonated LIVE deployer EOA (never the player wallet) */
  deployedBy: string;
  layer: SimOverlayLayer;
  /** the recommended pin when the fork reports one */
  pin: number | null;
  /** the anvil fork block reported by anvil_nodeInfo (may be null on a head fork) */
  forkBlock: number | null;
  deployedAt: number;
  notes: Record<string, string | null>;
}

const KEY_PREFIX = "dys.sim.overlay.v1:";
const ADDRESS_RE = /^0x[0-9a-fA-F]{40}$/;

const cache = new Map<string, SimOverlayRecord | null>();
const listeners = new Set<() => void>();
let storageWired = false;

function keyFor(rpcUrl: string): string {
  return KEY_PREFIX + normalizeRpcUrl(rpcUrl);
}

function notify(): void {
  for (const fn of listeners) fn();
}

function wireStorage(): void {
  if (storageWired || typeof window === "undefined" || typeof window.addEventListener !== "function") return;
  storageWired = true;
  window.addEventListener("storage", (e) => {
    if (e.key !== null && !e.key.startsWith(KEY_PREFIX)) return;
    cache.clear();
    notify();
  });
}

function parseRecord(text: string): SimOverlayRecord | null {
  try {
    const r = JSON.parse(text) as Partial<SimOverlayRecord>;
    if (r === null || typeof r !== "object") return null;
    if (r.v !== 1) return null;
    if (typeof r.rpc !== "string" || typeof r.chainId !== "number" || typeof r.deployedBy !== "string") return null;
    if (!ADDRESS_RE.test(r.deployedBy)) return null;
    if (r.layer === null || typeof r.layer !== "object") return null;
    for (const name of SIM_LAYER_NAMES) {
      const a = (r.layer as Record<string, unknown>)[name];
      if (typeof a !== "string" || !ADDRESS_RE.test(a)) return null;
    }
    return {
      v: 1,
      rpc: r.rpc,
      chainId: r.chainId,
      deployedBy: r.deployedBy,
      layer: r.layer as SimOverlayLayer,
      pin: typeof r.pin === "number" ? r.pin : null,
      forkBlock: typeof r.forkBlock === "number" ? r.forkBlock : null,
      deployedAt: typeof r.deployedAt === "number" ? r.deployedAt : 0,
      notes: (r.notes ?? {}) as Record<string, string | null>,
    };
  } catch {
    return null;
  }
}

/** the runtime overlay for this RPC (null = none / unreadable / invalid) */
export function readSimOverlay(rpcUrl: string): SimOverlayRecord | null {
  const key = keyFor(rpcUrl);
  const hit = cache.get(key);
  if (hit !== undefined) return hit;
  let record: SimOverlayRecord | null = null;
  try {
    if (typeof window !== "undefined") {
      const text = window.localStorage.getItem(key);
      if (text !== null) record = parseRecord(text);
    }
  } catch {
    record = null;
  }
  cache.set(key, record);
  return record;
}

export function writeSimOverlay(rpcUrl: string, record: Omit<SimOverlayRecord, "v" | "rpc">): SimOverlayRecord {
  const full: SimOverlayRecord = { v: 1, rpc: normalizeRpcUrl(rpcUrl), ...record };
  const key = keyFor(rpcUrl);
  cache.set(key, full);
  try {
    if (typeof window !== "undefined") window.localStorage.setItem(key, JSON.stringify(full));
  } catch {
    /* storage unavailable — the in-memory cache still serves this session */
  }
  notify();
  return full;
}

/** clear the runtime overlay only (the fork-only player key is separate) */
export function clearSimOverlay(rpcUrl: string): void {
  const key = keyFor(rpcUrl);
  cache.set(key, null);
  try {
    if (typeof window !== "undefined") window.localStorage.removeItem(key);
  } catch {
    /* storage unavailable */
  }
  notify();
}

export function subscribeSimOverlay(fn: () => void): () => void {
  wireStorage();
  listeners.add(fn);
  return () => listeners.delete(fn);
}

/** React subscription (stable cached snapshot) */
export function useSimOverlay(rpcUrl: string): SimOverlayRecord | null {
  return useSyncExternalStore(
    subscribeSimOverlay,
    () => readSimOverlay(rpcUrl),
    () => null
  );
}

/** the address table for display: runtime overlay first, fixture second */
export function simLayerAddresses(rpcUrl: string): SimOverlayLayer {
  return readSimOverlay(rpcUrl)?.layer ?? simLayerConfig.layer;
}

/** precedence resolution — callers gate on simLayerActive BEFORE this */
export function resolveSimLayerAddress(name: SimLayerName, rpcUrl: string): Address | null {
  const a = readSimOverlay(rpcUrl)?.layer[name] ?? simLayerConfig.layer[name];
  return a && ADDRESS_RE.test(a) ? (a as Address) : null;
}

export interface OverlayCodeCheck {
  overlay: SimOverlayRecord | null;
  /** layer names with NO code at the recorded/static address */
  missing: SimLayerName[];
  /** runtime overlay present but code is absent → the fork was reset/re-pinned */
  stale: boolean;
  /** the record was deployed on a different chain id */
  chainMismatch: boolean;
}

/**
 * Is the overlay still live on this fork? Code is the honest probe: an anvil
 * reset or re-pin drops the deployed layer while localStorage survives.
 */
export async function checkOverlayCode(
  client: Pick<PublicClient, "getCode">,
  rpcUrl: string,
  chainId: number | null
): Promise<OverlayCodeCheck> {
  const overlay = readSimOverlay(rpcUrl);
  const addresses = overlay?.layer ?? simLayerConfig.layer;
  const missing: SimLayerName[] = [];
  for (const name of SIM_LAYER_NAMES) {
    try {
      const code = await client.getCode({ address: addresses[name] as Address });
      if (!code || code === "0x") missing.push(name);
    } catch {
      missing.push(name);
    }
  }
  return {
    overlay,
    missing,
    stale: overlay !== null && (missing.length > 0 || (chainId !== null && overlay.chainId !== chainId)),
    chainMismatch: overlay !== null && chainId !== null && overlay.chainId !== chainId,
  };
}
